{
  "jdAnalysis": {
    "responsibilities": [
      "分析企业财务报表与现金流",
      "整理授信调查材料",
      "跟踪贷后经营变化",
      "形成风险提示供审批部门参考"
    ],
    "hardRequirements": [
      "金融、会计或经济相关本科及以上学历",
      "3年以上对公信贷或企业信用分析相关经验",
      "能够清晰说明财务数据口径与个人职责"
    ],
    "implicitRequirements": [
      "具备企业财务报表与现金流的独立分析能力",
      "能够持续跟踪存量客户贷后经营变化并识别异常",
      "能够将复杂经营与财务信息整理为清晰的风险提示",
      "具备严谨的数据口径意识和职责边界意识",
      "能够与客户经理、风控及审批部门进行材料复核与沟通",
      "对制造业客户经营特征有一定理解",
      "具备使用数据工具辅助查询与分析的学习意愿"
    ],
    "keywords": [
      "对公信用风险",
      "企业财务报表",
      "现金流分析",
      "授信调查材料",
      "贷后跟踪",
      "风险提示",
      "审批参考",
      "制造业客户",
      "SQL数据查询",
      "数据口径",
      "个人职责"
    ],
    "idealCandidate": "具备3年以上对公信贷或企业信用分析经验，能独立分析企业财务报表与现金流，熟练整理授信调查材料，持续跟踪贷后经营变化，并能将异常信息转化为供审批部门参考的风险提示；同时能够清晰说明财务数据口径与个人职责边界，有制造业客户分析经验或SQL数据查询能力者更佳。",
    "coreCompetencies": [
      {
        "name": "企业财务与现金流分析",
        "importance": "high",
        "description": "能够阅读和分析企业财务报表，重点识别收入、应收账款、现金流等关键科目的变化与异常。"
      },
      {
        "name": "授信调查材料整理",
        "importance": "high",
        "description": "能够按照授信流程收集、校验和整理企业调查材料，保证材料完整、口径清晰，可供复核和审批参考。"
      },
      {
        "name": "贷后经营变化跟踪",
        "importance": "high",
        "description": "能够按季度或既定周期更新存量客户贷后跟踪台账，持续关注经营变化和报表异常。"
      },
      {
        "name": "风险信息整理与提示",
        "importance": "high",
        "description": "能够将财务数据、经营变化和排查线索整理为简明风险提示，提交客户经理、风控或审批部门复核参考。"
      },
      {
        "name": "数据口径与职责说明",
        "importance": "high",
        "description": "能够准确说明财务数据来源、统计口径和个人在材料整理、分析及跟踪中的具体职责，不混淆申请额度与实际授信、放款金额。"
      },
      {
        "name": "制造业客户分析",
        "importance": "medium",
        "description": "具备制造业客户经营资料和财务报表分析经验，能够理解制造业收入、应收账款与回款特征，属于加分能力。"
      },
      {
        "name": "SQL数据查询",
        "importance": "medium",
        "description": "能够使用SQL进行数据查询和辅助分析，提升贷后跟踪与风险信息整理效率，属于加分能力而非硬性要求。"
      }
    ]
  }
}
